using System.Data;using Microsoft.Data.SqlClient;using StockSyncAI.Api.Configuration;using StockSyncAI.Api.Models;
namespace StockSyncAI.Api.Services;
public sealed class SqlPosWriteGateway(PosConnectionSettings settings):IPosWriteGateway
{
 public async Task<PosPostingResult> PostAsync(PostingSnapshot snapshot,CancellationToken token=default)
 {await using var connection=new SqlConnection(settings.GetWriteConnectionString());await connection.OpenAsync(token);await using var transaction=(SqlTransaction)await connection.BeginTransactionAsync(IsolationLevel.ReadCommitted,token);var ids=new List<string>();var newIds=new Dictionary<string,object>(StringComparer.Ordinal);
  try{foreach(var line in snapshot.Lines){object? productId=line.ProductId;if(line.DecisionSource==ReviewDecisionSources.NewProductCandidate){var key=$"{line.ProductName}\u001f{line.Category}\u001f{line.Barcode}\u001f{line.SellingPrice}\u001f{line.Discount}";if(!newIds.TryGetValue(key,out productId!)){await using var product=connection.CreateCommand();product.Transaction=transaction;product.CommandTimeout=30;product.CommandText="""INSERT INTO [dbo].[addpro] ([proname],[pro_cost],[proprice],[procat],[pro_barcode],[pro_discount]) OUTPUT INSERTED.[pro_ID] VALUES (@name,@cost,@price,@category,@barcode,@discount);""";Add(product,"@name",line.ProductName);Add(product,"@cost",line.PerUnitCost);Add(product,"@price",line.SellingPrice);Add(product,"@category",line.Category);Add(product,"@barcode",line.Barcode);Add(product,"@discount",line.Discount);productId=await product.ExecuteScalarAsync(token)??throw new InvalidOperationException("POS did not return the new product identifier.");newIds[key]=productId;ids.Add(Convert.ToString(productId,System.Globalization.CultureInfo.InvariantCulture)??string.Empty);}}
   await using var stock=connection.CreateCommand();stock.Transaction=transaction;stock.CommandTimeout=30;stock.CommandText="""INSERT INTO [dbo].[stockin] ([vname],[proname],[proquantity],[procost],[proprice],[proexpiry],[pro_barcode]) VALUES (@vendor,@name,@quantity,@cost,@amount,@expiry,@barcode);""";Add(stock,"@vendor",snapshot.VendorName);Add(stock,"@name",line.ProductName);Add(stock,"@quantity",line.TotalUnits);Add(stock,"@cost",line.PerUnitCost);Add(stock,"@amount",line.NetLineAmount);Add(stock,"@expiry",line.ExpiryDate);Add(stock,"@barcode",line.Barcode);if(await stock.ExecuteNonQueryAsync(token)!=1)throw new InvalidOperationException("POS did not confirm the stock row insertion.");}
   try{await transaction.CommitAsync(token);}catch(Exception e){throw new PosOutcomeUnknownException("The POS transaction outcome could not be confirmed. Do not retry until reconciled.",e);}return new(ids,snapshot.Lines.Count,DateTimeOffset.UtcNow);}
  catch(PosOutcomeUnknownException){throw;}catch(Exception e){try{await transaction.RollbackAsync(CancellationToken.None);}catch(Exception rollback){throw new PosOutcomeUnknownException("The POS transaction rollback could not be confirmed. Do not retry until reconciled.",rollback);}throw new PosConfirmedRollbackException("The POS transaction was rolled back; the posting can be retried after correcting the error.",e);}}
 private static void Add(SqlCommand c,string n,object? v)=>c.Parameters.AddWithValue(n,v??DBNull.Value);
}
